package pzvrphysicality;

import java.lang.ref.WeakReference;import java.util.*;import local.pzvr.*;import viewpoint.packs.*;import viewpoint.render.SceneData;import viewpointvr.physics.CollisionShape;import zombie.characters.IsoPlayer;import zombie.inventory.InventoryItem;import zombie.inventory.types.Moveable;import zombie.iso.objects.IsoWorldInventoryObject;

/** Original-item physical carry. Only a confirmed native pickup can establish a captured grab-relative pose. */
public final class MoveableCarry {
 private record Lease(WeakReference<IsoPlayer> actor,WeakReference<InventoryItem> item,WeakReference<Object> cell,PackBind binding,MoveableGeometry.Geometry geometry,int side,long itemEpoch,long modeEpoch,long rigGeneration,double units,float[] rawGrab,float[] itemPose,float[] actorPosition,long created){Lease{rawGrab=rawGrab.clone();itemPose=itemPose.clone();actorPosition=actorPosition.clone();}}
 public record Target(IsoPlayer actor,InventoryItem item,PackBind binding,MoveablePackCpu.Data geometry,int side,Object scene,XrBackend.Frame input,long rigGeneration,long itemEpoch,long modeEpoch,long time,double units,float mass,CollisionShape shape,float[] pose){public Target{pose=pose.clone();}public float[] pose(){return pose.clone();}}
 private record Correction(Target target,float[] pose){Correction{pose=pose.clone();}}
 private record PlannedDrop(Lease lease,float[] pose,long time){PlannedDrop{pose=pose.clone();}}
 public record Drop(MoveableGeometry.Geometry geometry,float[] pose){public Drop{pose=pose.clone();}public float[] pose(){return pose.clone();}}
 private static final MoveableCarryPose[] policy={new MoveableCarryPose(),new MoveableCarryPose()};private static final Lease[] pending=new Lease[2],held=new Lease[2];private static final Correction[] corrected=new Correction[2];
 private static final PlannedDrop[] drops=new PlannedDrop[2];
 private static final boolean[] received=new boolean[2];
 private static String detail="Moveable physical carries waiting";
 private static boolean actor(IsoPlayer p){return MoveableModels.enabled()&&Main.ready()&&p!=null&&IsoPlayer.players.length>0&&IsoPlayer.players[0]==p&&!p.isDead()&&p.getVehicle()==null&&!zombie.network.GameClient.client&&!zombie.network.GameServer.server&&!zombie.GameTime.isGamePaused()&&Engine.active()&&Engine.worldPresent;}
 private static WorldRigFrame rig(IsoPlayer p,Object scene,long now){var r=scene==null?WorldRigCapture.latest:WorldRigCapture.forScene(scene,now);var latest=WorldRigCapture.latest;var input=Engine.latestInput;return actor(p)&&r!=null&&latest!=null&&r.actor()==p&&r.generation()==latest.generation()&&r.fresh(now)&&input!=null&&input.focused()&&input.time()==r.inputTime()?r:null;}
 private static boolean input(IsoPlayer p){return NativeItems.supportsPhysicalGestures(p)&&!p.hasTimedActions()&&!VrApi.fullHud()&&!VrApi.pointerActive()&&!zombie.ui.UIManager.isModalVisible()&&!zombie.core.Core.getInstance().isDoingTextEntry();}
 private static MoveableCarryPose.Provenance provenance(Lease l,InventoryItem item){return new MoveableCarryPose.Provenance(l.actor.get(),item,l.side,l.itemEpoch,l.rigGeneration,l.geometry.source().generation());}
 private static float[] raw(Math3.Pose pose){var p=pose.position();var q=pose.rotation();return new float[]{(float)p.x(),(float)p.y(),(float)p.z(),(float)q.x(),(float)q.y(),(float)q.z(),(float)q.w()};}
 private static boolean numeric(Lease l,InventoryItem item){return l!=null&&item!=null&&item==l.item.get()&&MoveableModels.packOnly(item)&&l.modeEpoch==MoveableModels.epoch()&&l.itemEpoch==NativeItems.epoch()&&item instanceof Moveable m&&ModelPacks.bind(m.getWorldSprite())==l.binding&&MoveablePackCpu.get(l.binding.model)==l.geometry.source()&&item.worldScale==l.geometry.scale();}
 private static boolean source(Lease l,InventoryItem item){return numeric(l,item)&&item.getWorldZRotation()==l.geometry.yaw()&&MoveableRenderHook.asset(l.binding.model,l.geometry.source())!=null;}
 public static synchronized void reserve(IsoPlayer p,InventoryItem item,IsoWorldInventoryObject source,int side,long itemEpoch){
  if(side<0||side>1)return;pending[side]=null;received[side]=false;policy[side].cancelPending();long now=System.nanoTime();var r=WorldRigCapture.latest;var input=Engine.latestInput;
  var raw=input==null?null:side==0?input.left():input.right();
  if(!actor(p)||r==null||r.actor()!=p||!r.fresh(now)||input==null||!input.focused()||input.time()<r.inputTime()||input.time()-r.inputTime()>150_000_000L||r.hand(side)==null||raw==null||!raw.tracked()||raw.grip()==null||itemEpoch!=NativeItems.epoch()||!(item instanceof Moveable m)||item.getWorldItem()!=source||source==null||source.getItem()!=item||item.getContainer()!=null)return;
  var binding=ModelPacks.bind(m.getWorldSprite());var data=binding==null?null:MoveablePackCpu.get(binding.model);if(data==null||MoveableRenderHook.asset(binding.model,data)==null)return;
  try{var geometry=MoveableGeometry.fit(binding,data,item.getWorldZRotation(),item.worldScale);var world=MoveableRenderHook.groundPose(item,source);var l=new Lease(new WeakReference<>(p),new WeakReference<>(item),new WeakReference<>(p.getCell()),binding,geometry,side,itemEpoch,MoveableModels.epoch(),r.generation(),r.hand(side).units(),raw(raw.grip()),world,new float[]{p.getX(),p.getY(),p.getZ()},now);pending[side]=l;detail="Exact moveable raw grip and item pose reserved";}catch(IllegalArgumentException unsupported){detail="Moveable grab pose unavailable; original pickup retained";}
 }
 public static synchronized void received(IsoPlayer p,InventoryItem item,int side,long itemEpoch){if(side<0||side>1)return;var l=pending[side];if(l==null||!actor(p)||l.actor.get()!=p||l.cell.get()!=p.getCell()||l.itemEpoch!=itemEpoch||!numeric(l,item)||item.getWorldZRotation()!=l.geometry.yaw()||NativeItems.hand(p,side)!=item||NativeItems.hand(p,1-side)==item||item.getWorldItem()!=null||item.getContainer()!=p.getInventory()||!p.getInventory().contains(item)){policy[side].cancelPending();pending[side]=null;received[side]=false;return;}received[side]=true;detail="Native moveable pickup confirmed; waiting for matching render hand";}
 private static void commit(int side,IsoPlayer p,WorldRigFrame r,long now){var l=pending[side];if(l==null||!received[side]||r==null)return;var item=l.item.get();var input=Engine.latestInput;var raw=input==null?null:side==0?input.left():input.right();if(!source(l,item)||l.actor.get()!=p||l.cell.get()!=p.getCell()||l.rigGeneration!=r.generation()||r.hand(side)==null||raw==null||!raw.tracked()||raw.grip()==null||NativeItems.hand(p,side)!=item||NativeItems.hand(p,1-side)==item||item.getWorldItem()!=null||item.getContainer()!=p.getInventory()||!p.getInventory().contains(item)||Math.abs(p.getX()-l.actorPosition[0])>.005||Math.abs(p.getY()-l.actorPosition[1])>.005||Math.abs(p.getZ()-l.actorPosition[2])>.005||Math.abs(r.hand(side).units()-l.units)>.0001||now<l.created||now-l.created>10_000_000_000L){pending[side]=null;received[side]=false;return;}try{var hand=MoveableCarryPose.requestedHand(StoragePose.hand(r.hand(side)),raw(raw.grip()),l.rawGrab,l.units);policy[side].reserve(provenance(l,item),l.itemPose,hand,l.created);if(policy[side].commit(provenance(l,item),now)){held[side]=l;corrected[side]=null;detail="Original moveable follows its captured physical grab";}}catch(IllegalArgumentException invalid){policy[side].clear();}pending[side]=null;received[side]=false;}
 public static synchronized void cancel(){for(int side=0;side<2;side++){pending[side]=null;received[side]=false;drops[side]=null;policy[side].cancelPending();}}
 public static synchronized void clear(){for(int side=0;side<2;side++){policy[side].clear();pending[side]=held[side]=null;received[side]=false;corrected[side]=null;drops[side]=null;}detail="Moveable physical carries waiting";}
 /** Contact mode retirement clears only its visual constraint, retaining the confirmed native carry. */
 public static synchronized void clearCorrections(){Arrays.fill(corrected,null);}
 public static synchronized List<PackBind> models(){var result=new ArrayList<PackBind>();for(int side=0;side<2;side++)for(var l:new Lease[]{pending[side],held[side],drops[side]==null?null:drops[side].lease})if(l!=null&&numeric(l,l.item.get())&&actor(l.actor.get())&&!result.contains(l.binding))result.add(l.binding);return List.copyOf(result);}
 private static boolean owns(Lease l,IsoPlayer p,InventoryItem item,WorldRigFrame r){return l!=null&&r!=null&&source(l,item)&&l.actor.get()==p&&l.cell.get()==p.getCell()&&l.rigGeneration==r.generation()&&r.hand(l.side)!=null&&Math.abs(r.hand(l.side).units()-l.units)<.0001&&NativeItems.hand(p,l.side)==item&&NativeItems.hand(p,1-l.side)!=item&&item.getWorldItem()==null&&item.getContainer()==p.getInventory()&&p.getInventory().contains(item);}
 public static synchronized List<Target> targets(SceneData scene,IsoPlayer p,long now){var r=rig(p,scene,now);var result=new ArrayList<Target>();for(int side=0;side<2;side++){commit(side,p,r,now);var l=held[side];var item=l==null?null:l.item.get();if(!owns(l,p,item,r)){if(l!=null){policy[side].clear();held[side]=null;corrected[side]=null;detail="Moveable carry retired; native inventory retained";}continue;}if(!input(p))continue;var input=Engine.latestInput;var raw=side==0?input.left():input.right();if(raw==null||!raw.tracked()||raw.grip()==null){policy[side].clear();held[side]=null;corrected[side]=null;continue;}try{var pose=policy[side].pose(provenance(l,item),StoragePose.hand(r.hand(side)));float mass=item.getActualWeight();if(pose!=null&&Float.isFinite(mass)&&mass>0&&mass<=20)result.add(new Target(p,item,l.binding,l.geometry.source(),side,scene,input,r.generation(),l.itemEpoch,l.modeEpoch,now,l.units,Math.max(.01f,mass),l.geometry.shape(),pose));}catch(IllegalArgumentException unsupported){policy[side].clear();held[side]=null;corrected[side]=null;}}return List.copyOf(result);}
 public static synchronized boolean current(Target t,long now){if(t==null||now<t.time||now-t.time>150_000_000L||t.side<0||t.side>1)return false;var l=held[t.side];return l!=null&&input(t.actor)&&t.geometry==l.geometry.source()&&t.modeEpoch==MoveableModels.epoch()&&t.itemEpoch==NativeItems.epoch()&&t.input==Engine.latestInput&&t.input.focused()&&owns(l,t.actor,t.item,rig(t.actor,t.scene,now));}
 /** External contact owner can offer only a bounded rigid pose for the exact current candidate. */
 public static synchronized boolean corrected(Target target,float[] pose){if(!current(target,System.nanoTime())||pose==null||pose.length!=7)return false;try{MoveableGeometry.world(pose);double distance=0;for(int n=0;n<3;n++)distance+=(pose[n]-target.pose[n])*(pose[n]-target.pose[n]);if(distance>.04*.04*target.units*target.units)return false;double dot=0;for(int n=3;n<7;n++)dot+=pose[n]*target.pose[n];if(2*Math.acos(Math.min(1,Math.abs(dot)))>Math.toRadians(15))return false;corrected[target.side]=new Correction(target,pose);return true;}catch(IllegalArgumentException invalid){return false;}}
 public static synchronized float[] visual(Target target){var correction=target==null?null:corrected[target.side];return correction!=null&&current(correction.target,System.nanoTime())&&correction.target.item==target.item&&correction.target.scene==target.scene&&correction.target.input==target.input&&correction.target.geometry==target.geometry&&Arrays.equals(correction.target.pose,target.pose)?correction.pose.clone():target==null?null:target.pose();}
 public static synchronized MoveableGeometry.Geometry geometry(InventoryItem item){for(var l:held)if(l!=null&&source(l,item))return l.geometry;return null;}
 public static synchronized float[] released(IsoPlayer p,InventoryItem item,int side,long itemEpoch){if(side<0||side>1)return null;var l=held[side];var r=rig(p,null,System.nanoTime());float[] result=null;if(l!=null&&r!=null&&l.actor.get()==p&&l.item.get()==item&&l.itemEpoch==itemEpoch&&l.rigGeneration==r.generation()&&l.cell.get()==p.getCell()&&source(l,item)&&r.hand(side)!=null)try{result=policy[side].pose(provenance(l,item),StoragePose.hand(r.hand(side)));}catch(IllegalArgumentException invalid){result=null;}policy[side].clear();held[side]=pending[side]=null;corrected[side]=null;return result;}
 public static synchronized void planDrop(IsoPlayer p,InventoryItem item,int side,long itemEpoch){if(side<0||side>1)return;drops[side]=null;var l=held[side];var r=rig(p,null,System.nanoTime());if(!owns(l,p,item,r)||l.itemEpoch!=itemEpoch)return;try{var pose=policy[side].pose(provenance(l,item),StoragePose.hand(r.hand(side)));var correction=corrected[side];if(correction!=null&&current(correction.target,System.nanoTime())&&Arrays.equals(correction.target.pose,pose))pose=correction.pose.clone();if(pose!=null)drops[side]=new PlannedDrop(l,pose,System.nanoTime());}catch(IllegalArgumentException unsupported){drops[side]=null;}}
 public static synchronized Drop dropped(IsoPlayer p,InventoryItem item,int side,long itemEpoch){if(side<0||side>1)return null;var plan=drops[side];drops[side]=null;var next=MoveableRenderHook.geometry(item);var r=rig(p,null,System.nanoTime());Drop result=null;if(plan!=null&&r!=null&&next!=null&&numeric(plan.lease,item)&&plan.lease.actor.get()==p&&plan.lease.cell.get()==p.getCell()&&plan.lease.itemEpoch==itemEpoch&&plan.lease.rigGeneration==r.generation()&&System.nanoTime()>=plan.time&&System.nanoTime()-plan.time<10_000_000_000L)try{result=new Drop(next,MoveableGeometry.rebase(plan.pose,plan.lease.geometry,next));}catch(IllegalArgumentException unsupported){result=null;}policy[side].clear();pending[side]=held[side]=null;corrected[side]=null;return result;}
 public static synchronized String status(){return detail+"; hotbar moveables without a captured grab use native held models";}
 private MoveableCarry(){}
}
